	@Test
	void concurrentExecutionsKeepSeparateAccumulatorsWhileSharingPosteriorCells(@TempDir Path tempDir)
			throws Exception {
		LmdbOperatorFeedbackStats statistics = new LmdbOperatorFeedbackStats(tempDir.resolve("feedback"));
		RuntimeFeedbackContract contract = contract();
		RuntimeFeedbackTarget first = statistics.resolveRuntimeFeedbackTarget(contract);
		RuntimeFeedbackTarget second = statistics.resolveRuntimeFeedbackTarget(contract);
		CountDownLatch ready = new CountDownLatch(2);
		CountDownLatch start = new CountDownLatch(1);

		try (ExecutorService executor = Executors.newFixedThreadPool(2)) {
			Future<?> firstRun = executor
					.submit(() -> executeAndPublish(statistics, contract, first, 3L, ready, start));
			Future<?> secondRun = executor
					.submit(() -> executeAndPublish(statistics, contract, second, 7L, ready, start));
			ready.await();
			start.countDown();
			firstRun.get();
			secondRun.get();
		}

		assertEquals(3.0d, first.actualRowsSum());
		assertEquals(7.0d, second.actualRowsSum());
		FrontierLearningModel.PosteriorSnapshot logical = statistics.logicalPosterior(
				LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS);
		FrontierLearningModel.PosteriorSnapshot physical = statistics.physicalPosterior(
				LOGICAL, PHYSICAL, APPLICABILITY, FrontierCostDimension.SOURCE_ROWS_SCANNED);
		assertEquals(2L, logical.exactEvidenceCount());
		assertEquals(2L, physical.exactEvidenceCount());
	}

	@Test
	void preboundOpenCloseAndRootPublicationAllocateNoLearningObjects(@TempDir Path tempDir) {
		LmdbOperatorFeedbackStats statistics = new LmdbOperatorFeedbackStats(tempDir.resolve("feedback"));
		RuntimeFeedbackContract contract = contract();
		RuntimeFeedbackTarget[] singleton = new RuntimeFeedbackTarget[1];
		for (int iteration = 0; iteration < 16_384; iteration++) {
			RuntimeFeedbackTarget target = statistics.resolveRuntimeFeedbackTarget(contract);
			assertTrue(target.active());
			executeAndPublish(statistics, contract, target, singleton);
		}
		RuntimeFeedbackTarget[] measured = resolveTargets(statistics, contract, 4_096);

		com.sun.management.ThreadMXBean threadMxBean = (com.sun.management.ThreadMXBean) ManagementFactory
				.getThreadMXBean();
		assertTrue(threadMxBean.isThreadAllocatedMemorySupported());
		boolean allocationTrackingEnabled = threadMxBean.isThreadAllocatedMemoryEnabled();
		try {
			if (!allocationTrackingEnabled) {
				threadMxBean.setThreadAllocatedMemoryEnabled(true);
			}
			long threadId = Thread.currentThread().threadId();
			long counterBaselineBefore = threadMxBean.getThreadAllocatedBytes(threadId);
			long counterBaselineAfter = threadMxBean.getThreadAllocatedBytes(threadId);
			long counterReadBytes = counterBaselineAfter - counterBaselineBefore;
			long before = threadMxBean.getThreadAllocatedBytes(threadId);
			for (RuntimeFeedbackTarget target : measured) {
				executeAndPublish(statistics, contract, target, singleton);
			}
			long rawAllocatedBytes = threadMxBean.getThreadAllocatedBytes(threadId) - before;
			long allocatedBytes = rawAllocatedBytes - counterReadBytes;

			assertEquals(0L, allocatedBytes,
					"Open, close, direct-cell publication, lifecycle verification, and lease release must allocate nothing"
							+ " (raw=" + rawAllocatedBytes + ", counterRead=" + counterReadBytes + ")");
		} finally {
			if (!allocationTrackingEnabled) {
				threadMxBean.setThreadAllocatedMemoryEnabled(false);
			}
		}
	}

	private static RuntimeFeedbackTarget[] resolveTargets(LmdbOperatorFeedbackStats statistics,
			RuntimeFeedbackContract contract, int count) {
		RuntimeFeedbackTarget[] targets = new RuntimeFeedbackTarget[count];
		for (int index = 0; index < targets.length; index++) {
			targets[index] = statistics.resolveRuntimeFeedbackTarget(contract);
			assertTrue(targets[index].active());
		}
		return targets;
	}

	private static void executeAndPublish(LmdbOperatorFeedbackStats statistics, RuntimeFeedbackContract contract,
			RuntimeFeedbackTarget target, RuntimeFeedbackTarget[] singleton) {
		target.open();
		target.close(1L, 1.0d, 1L, 0L, 0L, 0L, 0L, 0L, 0L, 0L,
				EvaluationStatistics.TerminationClassification.EXHAUSTED);
		target.recordActualPhysicalImplementation(contract.physicalImplementationId());
		singleton[0] = target;
		statistics.publishRuntimeFeedbackTargets(singleton, 1, true);
	}

	private static void executeAndPublish(LmdbOperatorFeedbackStats statistics, RuntimeFeedbackContract contract,
			RuntimeFeedbackTarget target, long rows, CountDownLatch ready, CountDownLatch start) {
		try {
			ready.countDown();
			start.await();
			target.open();
			target.close(rows, rows, rows, 0L, 0L, 0L, 0L, 0L, 0L, 0L,
					EvaluationStatistics.TerminationClassification.EXHAUSTED);
			target.recordActualPhysicalImplementation(contract.physicalImplementationId());
			statistics.publishRuntimeFeedbackTargets(new RuntimeFeedbackTarget[] { target }, 1, true);
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			throw new AssertionError(interrupted);
		}
	}

	private static RuntimeFeedbackContract contract() {
		return contract(APPLICABILITY, RuntimeFeedbackContract.DependentPredictionVector.UNKNOWN);
	}

	private static RuntimeFeedbackContract contract(LearningApplicability applicability) {
		return contract(applicability, RuntimeFeedbackContract.DependentPredictionVector.UNKNOWN);
	}

	private static RuntimeFeedbackContract contract(
			RuntimeFeedbackContract.DependentPredictionVector dependentPrediction) {
		return contract(APPLICABILITY, dependentPrediction);
	}

	private static RuntimeFeedbackContract contract(LearningApplicability applicability,
			RuntimeFeedbackContract.DependentPredictionVector dependentPrediction) {
		RuntimeFeedbackContract.PredictionVector prediction = new RuntimeFeedbackContract.PredictionVector(
				1.0d, 1.0d, 1.0d, 1.0d, 0.0d, 1.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
		return new RuntimeFeedbackContract(
				new LmdbRuntimeFeedbackDescriptor(null, null, LOGICAL, applicability, PHYSICAL),
				prediction, prediction, dependentPrediction, dependentPrediction,
				1.0d, 1.0d, 1.0d, Double.POSITIVE_INFINITY,
				RuntimeFeedbackContract.SemanticKind.ORDINARY,
				RuntimeFeedbackContract.Algorithm.STREAMING_CORRELATED,
				RuntimeFeedbackContract.Access.EXACT_LOOKUP, PHYSICAL.hashCode(), 2L, 2L, 1L,
				RuntimeFeedbackContract.ADMIT_LOGICAL | RuntimeFeedbackContract.ADMIT_PHYSICAL
						| RuntimeFeedbackContract.ADMIT_LIFECYCLE
						| RuntimeFeedbackContract.EXACT_FACT_ELIGIBLE);
	}

	private static RuntimeFeedbackContract semiAntiContract() {
		RuntimeFeedbackContract.PredictionVector prediction = new RuntimeFeedbackContract.PredictionVector(
				1.0d, 7.0d, 1.0d, 7.0d, 1.0d, 1.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
		RuntimeFeedbackContract.DependentPredictionVector dependent = new RuntimeFeedbackContract.DependentPredictionVector(
				0.0d, 1.0d, 7.0d, 31.0d, 1.0d, 7.0d, 1.0d, 0.0d, 0.0d, 0.0d);
		return new RuntimeFeedbackContract(
				new LmdbRuntimeFeedbackDescriptor(null, null, LOGICAL, APPLICABILITY, PHYSICAL),
				prediction, prediction, dependent, dependent,
				1.0d, 7.0d, 7.0d, Double.POSITIVE_INFINITY,
				RuntimeFeedbackContract.SemanticKind.EXISTS,
				RuntimeFeedbackContract.Algorithm.STREAMING_CORRELATED,
				RuntimeFeedbackContract.Access.EXACT_LOOKUP, PHYSICAL.hashCode(), 2L, 2L, 1L,
				RuntimeFeedbackContract.ADMIT_LOGICAL | RuntimeFeedbackContract.ADMIT_PHYSICAL
						| RuntimeFeedbackContract.ADMIT_SEMI_ANTI);
	}
